        if (count < 1 || count > perRow) {
            throw new IllegalArgumentException("count must be between 1 and " + perRow);
        }
        for (int i = 0; i < rows; i++) {
            int r = rows - 1 - i;
            int run = 0;
            for (int c = 0; c < perRow; c++) {
