        expect(IllegalArgumentException.class, () -> o.findBlock(0), "zero");
        expect(IllegalArgumentException.class, () -> o.findBlock(7), "wider than the hall");
    }

    static void testReserveOnce() {
        BoxOffice o = office();
        Booking a = o.reserveOnce("req-1", "ana", "A1", "A2");
