        BoxOffice o = office();
        o.setPricing(PriceRules.flat(10));
        eq(10, o.reserve("ana", "A1").priceCents(), "applies");
    }

    static void testReserveOnce() {
        BoxOffice o = office();
        Booking a = o.reserveOnce("req-1", "ana", "A1", "A2");
